#!/usr/bin/env python3
"""Build the full competitive analysis HTML report with embedded charts."""

import sys, os
sys.path.insert(0, '/logs/agent/sessions/skills/report-generator/scripts')

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from io import BytesIO
import base64

# ── Load & prepare data ────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv', encoding='utf-8-sig')

APPS_RAW = ['ChatGPT', 'Claude', 'Google_Gemini', 'Microsoft_Copilot', 'Perplexity']
APPS_LABEL = {
    'ChatGPT': 'ChatGPT',
    'Claude': 'Claude',
    'Google_Gemini': 'Google Gemini',
    'Microsoft_Copilot': 'MS Copilot',
    'Perplexity': 'Perplexity',
}
LABELS = [APPS_LABEL[a] for a in APPS_RAW]

# App colors (brand-ish palette)
APP_COLORS = {
    'ChatGPT':            '#10a37f',
    'Claude':             '#d97706',
    'Google_Gemini':      '#4285f4',
    'Microsoft_Copilot':  '#0078d4',
    'Perplexity':         '#7c3aed',
}
COLORS = [APP_COLORS[a] for a in APPS_RAW]

THEME_COLS = ['Accuracy/Logic Issues', 'Bugs/Performance', 'Pricing/Subscription', 'General']
THEME_COLORS = {
    'Accuracy/Logic Issues': '#ef4444',
    'Bugs/Performance':      '#f97316',
    'Pricing/Subscription':  '#8b5cf6',
    'General':               '#94a3b8',
}

# ── KPI computations ───────────────────────────────────────────────────────
avg_stars = df.groupby('App')['Star_Rating'].mean()
avg_sentiment = df.groupby('App')['Sentiment_Polarity'].mean()
avg_wc = df.groupby('App')['Word_Count'].mean()
avg_thumbs = df.groupby('App')['Thumbs_Up_Count'].mean()

theme_counts = df.groupby(['App', 'Review_Theme']).size().unstack(fill_value=0)
theme_pcts = (theme_counts.div(theme_counts.sum(axis=1), axis=0) * 100)

# Star distribution
star_dist = df.groupby(['App', 'Star_Rating']).size().unstack(fill_value=0)

# Mismatch
df_nz = df[df['Sentiment_Polarity'] != 0.0]
mismatch_hi = df_nz[(df_nz['Star_Rating'] >= 4) & (df_nz['Sentiment_Polarity'] < -0.05)]
mismatch_lo = df_nz[(df_nz['Star_Rating'] <= 2) & (df_nz['Sentiment_Polarity'] > 0.05)]
mismatch_all = pd.concat([mismatch_hi, mismatch_lo])
total_nz = df_nz.groupby('App').size()
mismatch_rate = (mismatch_all.groupby('App').size() / total_nz * 100)
zero_pct = (df[df['Sentiment_Polarity'] == 0.0].groupby('App').size() / df.groupby('App').size() * 100)

wc_by_star = df.groupby('Star_Rating')['Word_Count'].mean()
corr_wc_thumbs = df['Word_Count'].corr(df['Thumbs_Up_Count'])

# Thumbs by theme
thumbs_theme = df.groupby(['App', 'Review_Theme'])['Thumbs_Up_Count'].mean().unstack()

# ── Chart helpers ──────────────────────────────────────────────────────────

def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=fig.get_facecolor())
    plt.close(fig)
    buf.seek(0)
    return 'data:image/png;base64,' + base64.b64encode(buf.read()).decode()


def apply_style(ax, title='', xlabel='', ylabel=''):
    ax.set_facecolor('#f8fafc')
    ax.spines[['top', 'right']].set_visible(False)
    ax.spines[['left', 'bottom']].set_color('#cbd5e1')
    ax.tick_params(colors='#475569', labelsize=9)
    ax.set_title(title, fontsize=12, fontweight='bold', color='#1e293b', pad=10)
    if xlabel: ax.set_xlabel(xlabel, fontsize=9, color='#64748b')
    if ylabel: ax.set_ylabel(ylabel, fontsize=9, color='#64748b')
    ax.yaxis.grid(True, color='#e2e8f0', linewidth=0.7)
    ax.set_axisbelow(True)


# ── Chart 1: Average Star Rating ──────────────────────────────────────────
def chart_avg_stars():
    vals = [avg_stars[a] for a in APPS_RAW]
    fig, ax = plt.subplots(figsize=(7, 3.5))
    fig.patch.set_facecolor('#ffffff')
    bars = ax.bar(LABELS, vals, color=COLORS, width=0.55, edgecolor='white', linewidth=0.8)
    ax.set_ylim(0, 5.4)
    for bar, v in zip(bars, vals):
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.07,
                f'{v:.2f}', ha='center', va='bottom', fontsize=9.5, fontweight='bold', color='#1e293b')
    apply_style(ax, 'Average Star Rating by App (1–5 scale)', '', 'Avg. Stars')
    ax.set_xticks(range(len(LABELS)))
    ax.set_xticklabels(LABELS, fontsize=9)
    fig.tight_layout()
    return fig_to_b64(fig)


# ── Chart 2: Mean Sentiment Polarity ──────────────────────────────────────
def chart_avg_sentiment():
    vals = [avg_sentiment[a] for a in APPS_RAW]
    fig, ax = plt.subplots(figsize=(7, 3.5))
    fig.patch.set_facecolor('#ffffff')
    bars = ax.bar(LABELS, vals, color=COLORS, width=0.55, edgecolor='white', linewidth=0.8)
    ax.set_ylim(0, 0.65)
    ax.axhline(0, color='#94a3b8', linewidth=1)
    for bar, v in zip(bars, vals):
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.008,
                f'{v:.3f}', ha='center', va='bottom', fontsize=9.5, fontweight='bold', color='#1e293b')
    apply_style(ax, 'Mean VADER Sentiment Polarity by App (−1 to +1)', '', 'Avg. Polarity')
    ax.set_xticks(range(len(LABELS)))
    ax.set_xticklabels(LABELS, fontsize=9)
    fig.tight_layout()
    return fig_to_b64(fig)


# ── Chart 3: Star rating distribution stacked ─────────────────────────────
def chart_star_dist():
    fig, ax = plt.subplots(figsize=(8, 4))
    fig.patch.set_facecolor('#ffffff')
    star_colors = ['#ef4444','#f97316','#facc15','#4ade80','#22c55e']
    bottoms = np.zeros(len(APPS_RAW))
    totals = np.array([star_dist.loc[a].sum() for a in APPS_RAW])
    for star, sc in zip([1,2,3,4,5], star_colors):
        vals = np.array([star_dist.loc[a].get(star, 0) for a in APPS_RAW]) / totals * 100
        bars = ax.bar(LABELS, vals, bottom=bottoms, color=sc, label=f'★{star}', width=0.6, edgecolor='white', linewidth=0.5)
        bottoms += vals
    ax.set_ylim(0, 105)
    apply_style(ax, 'Star Rating Distribution by App (%)', '', 'Share of Reviews (%)')
    ax.set_xticks(range(len(LABELS)))
    ax.set_xticklabels(LABELS, fontsize=9)
    ax.legend(loc='upper right', fontsize=8, title='Stars', title_fontsize=8, framealpha=0.9)
    fig.tight_layout()
    return fig_to_b64(fig)


# ── Chart 4: Thematic complaint breakdown ─────────────────────────────────
def chart_theme_grouped():
    complaint_themes = ['Accuracy/Logic Issues', 'Bugs/Performance', 'Pricing/Subscription']
    x = np.arange(len(APPS_RAW))
    width = 0.25
    fig, ax = plt.subplots(figsize=(9, 4))
    fig.patch.set_facecolor('#ffffff')
    for i, (theme, color) in enumerate([(t, THEME_COLORS[t]) for t in complaint_themes]):
        vals = [theme_pcts.loc[a, theme] if theme in theme_pcts.columns else 0 for a in APPS_RAW]
        offset = (i - 1) * width
        bars = ax.bar(x + offset, vals, width=width*0.9, color=color, label=theme, edgecolor='white', linewidth=0.6)
        for bar, v in zip(bars, vals):
            if v > 0.5:
                ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.1,
                        f'{v:.1f}%', ha='center', va='bottom', fontsize=7.5, color='#1e293b')
    ax.set_xticks(x)
    ax.set_xticklabels(LABELS, fontsize=9)
    apply_style(ax, 'Complaint Theme Rates by App (% of total reviews)', '', '% of App Reviews')
    ax.legend(fontsize=8, loc='upper right', framealpha=0.9)
    ax.set_ylim(0, 13)
    fig.tight_layout()
    return fig_to_b64(fig)


# ── Chart 5: Theme stacked 100% per app ───────────────────────────────────
def chart_theme_stacked():
    fig, ax = plt.subplots(figsize=(8, 4))
    fig.patch.set_facecolor('#ffffff')
    bottoms = np.zeros(len(APPS_RAW))
    for theme in THEME_COLS:
        vals = np.array([theme_pcts.loc[a, theme] if theme in theme_pcts.columns else 0 for a in APPS_RAW])
        ax.bar(LABELS, vals, bottom=bottoms, color=THEME_COLORS[theme], label=theme, width=0.6, edgecolor='white', linewidth=0.5)
        for j, (b, v) in enumerate(zip(bottoms, vals)):
            if v > 2.5:
                ax.text(j, b + v/2, f'{v:.1f}%', ha='center', va='center', fontsize=7.5, color='white', fontweight='bold')
        bottoms += vals
    ax.set_ylim(0, 105)
    apply_style(ax, 'Review Theme Composition by App (% of reviews)', '', '% of App Reviews')
    ax.set_xticks(range(len(LABELS)))
    ax.set_xticklabels(LABELS, fontsize=9)
    ax.legend(fontsize=8, loc='upper right', framealpha=0.9, title='Theme', title_fontsize=8)
    fig.tight_layout()
    return fig_to_b64(fig)


# ── Chart 6: Mismatch rates ────────────────────────────────────────────────
def chart_mismatch():
    vals = [mismatch_rate.get(a, 0) for a in APPS_RAW]
    hi_vals = [mismatch_hi.groupby('App').size().get(a, 0) / total_nz.get(a, 1) * 100 for a in APPS_RAW]
    lo_vals = [mismatch_lo.groupby('App').size().get(a, 0) / total_nz.get(a, 1) * 100 for a in APPS_RAW]
    x = np.arange(len(APPS_RAW))
    width = 0.35
    fig, ax = plt.subplots(figsize=(8, 4))
    fig.patch.set_facecolor('#ffffff')
    b1 = ax.bar(x - width/2, hi_vals, width, color='#f59e0b', label='High-Star / Neg Polarity', edgecolor='white')
    b2 = ax.bar(x + width/2, lo_vals, width, color='#6366f1', label='Low-Star / Pos Polarity (Sarcasm)', edgecolor='white')
    for bar, v in zip(list(b1) + list(b2), hi_vals + lo_vals):
